package cn.bidcheck.verification.engine;
import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Page;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;

class EnterpriseSubjectBindingsTest {
 private static final String PROJECT="北方中心综合楼装修工程",A="北方装饰有限公司",B="南方设计有限公司";
 private Rule rule(String predicate,String role){return new Rule("R", "提交有效营业执照",predicate,role,"营业执照","","营业执照","",cn.bidcheck.compat.Java8Api.mapOf(),"投标人须提交有效营业执照","",cn.bidcheck.compat.Java8Api.listOf());}
 private Page page(int number,String text){return new Page(number,text,"PAGE","TEXT",null);}
 private EvidenceCorpus corpus(String... text){List<Page> pages=new ArrayList<>();for(int i=0;i<text.length;i++)pages.add(page(i+1,text[i]));return new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new Document("b","p","BID","商务文件",1,"h","",pages,cn.bidcheck.compat.Java8Api.listOf())));}
 private String cover(){return "1.商务投标文件封面\n（"+PROJECT+"）\n投标文件\n投标人名称：（盖章）"+A;}
 private String letter(){return "3.投标函\n（"+A+"和"+B+"联合体）（以下称“我方”）已仔细研究招标文件。\n投标人（公章或授权专用章）："+A;}
 private String agreement(String project){return "6.联合体协议书\n联合体协议书\n"+A+"、"+B+"[所有成员单位名称]自愿组成："+A+"和"+B+"联合体，共同投标"+project+"/标段。\n1. "+A+"为"+A+"和"+B+"联合体牵头人。\n"+A+"负责施工部分，"+B+"负责设计部分。";}
 private List<Fact> facts(EvidenceCorpus c,Rule r){return c.nativeFacts(cn.bidcheck.compat.Java8Api.listOf(r),cn.bidcheck.compat.Java8Api.listOf());}
 private Fact material(EvidenceCorpus c,int index,String company){return new Fact("material-"+company,"MATERIAL",company,"营业执照","营业执照","营业执照","","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(c.all.get(index).id()),cn.bidcheck.compat.Java8Api.mapOf("contentPresent", true));}
 @Test void businessPredicatesShareExplicitBidderWithoutVisualRule(){for(String predicate:cn.bidcheck.compat.Java8Api.listOf("DECLARATION", "MATERIAL", "VALIDITY")){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover());cn.bidcheck.verification.engine.VerificationTypes.Rule r=rule(predicate,"投标人");assertEquals(cn.bidcheck.compat.Java8Api.listOf(A),DomainBindings.subjects("投标人",facts(c,r),c));}}
 @Test void fullCorpusBindingsDoNotDependOnRetrievedLicensePage(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),"营业执照\n名称："+A);assertEquals(cn.bidcheck.compat.Java8Api.listOf(A),DomainBindings.subjects("投标人",c.nativeFacts(cn.bidcheck.compat.Java8Api.listOf(rule("MATERIAL","投标人")),cn.bidcheck.compat.Java8Api.listOf(c.all.get(1))),c));}
 @Test void consortiumLetterEnumeratesBothNotOnlyCoverSigner(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter());assertEquals(cn.bidcheck.compat.Java8Api.setOf(A, B),new HashSet<>(DomainBindings.subjects("投标人",facts(c,rule("MATERIAL","投标人")),c)));}
 @Test void exactCurrentAgreementResetsHistoricalAttachmentScopeAndKeepsRolesSeparate(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),"合同协议书\n项目名称：其他地区历史装修工程",agreement(PROJECT));assertEquals("CURRENT_PROJECT",c.all.get(2).scopeContext().status());for(java.util.Map.Entry<java.lang.String, java.util.Set<java.lang.String>> wanted:cn.bidcheck.compat.Java8Api.mapOf("投标人", cn.bidcheck.compat.Java8Api.setOf(A, B), "联合体牵头人", cn.bidcheck.compat.Java8Api.setOf(A), "设计单位", cn.bidcheck.compat.Java8Api.setOf(B), "施工单位", cn.bidcheck.compat.Java8Api.setOf(A)).entrySet())assertEquals(wanted.getValue(),new HashSet<>(DomainBindings.subjects(wanted.getKey(),facts(c,rule("MATERIAL",wanted.getKey())),c)),wanted.getKey());}
 @Test void allMembersRemainSeparateAndOneLicenseCannotPassBoth(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter(),"营业执照\n名称："+A+"\n经营范围：装饰施工，企业登记有效，依法开展经营活动。");cn.bidcheck.verification.engine.VerificationTypes.Rule r=rule("MATERIAL","投标人");java.util.ArrayList<cn.bidcheck.verification.engine.VerificationTypes.Fact> fs=new ArrayList<>(facts(c,r));fs.add(material(c,2,A));Decision d=new RuleEvaluator(fs,c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(r);assertEquals("UNDETERMINED",d.status());assertEquals(cn.bidcheck.compat.Java8Api.setOf(A, B),new HashSet<>((List<String>)d.proof().get("subjects")));assertEquals(2,((List<?>)d.proof().get("children")).size());assertFalse(((List<?>)d.proof().get("completeMemberSet")).isEmpty());}
 @Test void individualLicenseFactsCanPassOnlyTheirOwnSubmissionObligations(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter(),"营业执照\n名称："+A+"\n企业营业执照正文", "营业执照\n名称："+B+"\n企业营业执照正文");cn.bidcheck.verification.engine.VerificationTypes.Rule r=rule("MATERIAL","投标人");java.util.ArrayList<cn.bidcheck.verification.engine.VerificationTypes.Fact> fs=new ArrayList<>(facts(c,r));fs.add(material(c,2,A));fs.add(material(c,3,B));cn.bidcheck.verification.engine.VerificationTypes.Decision d=new RuleEvaluator(fs,c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(r);assertEquals("PASS",d.status(),d.toString());assertEquals(2,((List<?>)d.proof().get("children")).size());}
 @Test void licenseCannotSelfDeclareItsOwnerToBeBidder(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus("投标文件\n项目名称："+PROJECT,"营业执照\n投标人名称："+A);assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void purchaserAndEmployerLabelsAreNeverBidderRoles(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus("投标文件\n项目名称："+PROJECT+"\n招标人名称："+A+"\n甲方名称："+B);assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void placeholdersAndDirectoryAreNeverBindings(){for(String text:cn.bidcheck.compat.Java8Api.listOf("投标文件\n项目名称："+PROJECT+"\n投标人：XX装饰有限公司", "投标文件\n项目名称："+PROJECT+"\n填写示例\n投标人："+A, "目录\n投标文件...........1\n投标人...........2\n投标人："+A)){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(text);assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}}
 @Test void foreignAgreementCannotResetCurrentProject(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),agreement("南方中心综合楼装修工程"));assertEquals("OTHER_PROJECT",c.all.get(1).scopeContext().status());assertEquals(cn.bidcheck.compat.Java8Api.listOf(A),DomainBindings.subjects("投标人",facts(c,rule("MATERIAL","投标人")),c));assertTrue(facts(c,rule("MATERIAL","联合体牵头人")).isEmpty());}
 @Test void nestedHistoricalHeadingOrExplicitForeignProjectWinsOverJointPhrase(){for(String text:cn.bidcheck.compat.Java8Api.listOf("历史项目\n"+agreement(PROJECT), agreement(PROJECT)+"\n项目名称：南方中心综合楼装修工程")){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),text);assertTrue(c.all.get(1).scopeContext().blocked());assertTrue(facts(c,rule("MATERIAL","联合体牵头人")).isEmpty());}}
 @Test void conflictingCompleteMembershipDoesNotChooseConvenientSet(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter(),agreement(PROJECT).replace(B,"西部设计有限公司"));assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void incompleteActualJointAgreementCannotFallBackToCoverOnly(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),"联合体协议书\n共同投标"+PROJECT+"/标段。\n成员另见附件。");assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void cachedBindingAttributesNeverOverrideAbsentRoleSource(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus("投标文件\n项目名称："+PROJECT,"营业执照\n名称："+A);cn.bidcheck.verification.engine.VerificationTypes.Source s=c.all.get(1);cn.bidcheck.verification.engine.VerificationTypes.Fact forged=new Fact("fake","RELATION","投标人","名称",A,A,"","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(s.id()),cn.bidcheck.compat.Java8Api.mapOf("object", A, "bindingMethod", "EXPLICIT_BIDDER_LABEL", "members", cn.bidcheck.compat.Java8Api.listOf(A)));assertFalse(EnterpriseSubjectBindings.grounded(forged,s));assertTrue(new ProofVerifier().verify(new ObjectMapper().valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", cn.bidcheck.compat.Java8Api.listOf(forged))),c.all).facts().isEmpty());}
 @Test void validReusableBindingMustRevalidateCurrentSourceAndKeepsScopeNarrow(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter());java.util.List<cn.bidcheck.verification.engine.VerificationTypes.Fact> fs=facts(c,rule("MATERIAL","投标人"));assertFalse(fs.isEmpty());cn.bidcheck.verification.engine.ProofVerifier.Verified checked=new ProofVerifier().verify(new ObjectMapper().valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", fs)),c.all);assertEquals(fs.size(),checked.facts().size());assertTrue(checked.facts().stream().allMatch(f->"CURRENT_BID_PARTY_ONLY".equals(f.attributes().get("proofScope"))));}
 @Test void cachedSubsetCannotHideConflictingCompleteCurrentAgreement(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter(),agreement(PROJECT).replace(B,"西部设计有限公司"));cn.bidcheck.verification.engine.VerificationTypes.Source source=c.all.get(1);List<Fact> cached=new ArrayList<>();for(String company:cn.bidcheck.compat.Java8Api.listOf(A, B))cached.add(new Fact(company,"RELATION","投标人","名称",company,company,"","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(source.id()),cn.bidcheck.compat.Java8Api.mapOf("object", company)));assertTrue(EnterpriseSubjectBindings.completeSet(cn.bidcheck.compat.Java8Api.listOf(A, B),c).isEmpty());assertEquals("SUBJECT_SET_INCOMPLETE",new RuleEvaluator(cached,c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(rule("MATERIAL","投标人")).gaps().get(0).code());}
 @Test void singleCachedCoverCompanyCannotHideExplicitJointBidWithMissingList(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),"投标函\n本次采用联合体方式投标，组成名单另见附件。");cn.bidcheck.verification.engine.VerificationTypes.Source s=c.all.get(0);cn.bidcheck.verification.engine.VerificationTypes.Fact cached=new Fact("cached","RELATION","投标人","名称",A,A,"","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(s.id()),cn.bidcheck.compat.Java8Api.mapOf("object", A));assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());assertEquals("SUBJECT_SET_INCOMPLETE",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(cached),c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(rule("MATERIAL","投标人")).gaps().get(0).code());}
 @Test void conditionalConsortiumInstructionsDoNotMakeSingleBidJoint(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),"投标函\n如为联合体投标应提交协议。\n若本次采用联合体方式投标，应列明全部成员。");assertEquals(cn.bidcheck.compat.Java8Api.listOf(A),DomainBindings.subjects("投标人",facts(c,rule("MATERIAL","投标人")),c));}
 @Test void companyAndRoleLineWrapsRetainExplicitAgreementRelations(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),agreement(PROJECT).replace("联合体牵头人","联\n合体牵头人").replace("负责施工部分","负责施工\n部分"));assertEquals(cn.bidcheck.compat.Java8Api.listOf(A),DomainBindings.subjects("联合体牵头人",facts(c,rule("MATERIAL","联合体牵头人")),c));assertEquals(cn.bidcheck.compat.Java8Api.listOf(A),DomainBindings.subjects("施工单位",facts(c,rule("MATERIAL","施工单位")),c));}
 @Test void cachedFalseLeadCannotUseNearbyOtherPartyAsProof(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),agreement(PROJECT));cn.bidcheck.verification.engine.VerificationTypes.Source s=c.all.get(1);cn.bidcheck.verification.engine.VerificationTypes.Fact forged=new Fact("fake-lead","RELATION","联合体牵头人","名称",B,B,"","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(s.id()),cn.bidcheck.compat.Java8Api.mapOf("object", B, "bindingMethod", "EXPLICIT_LEAD_MEMBER"));assertFalse(DomainBindings.currentRoleSource(forged,c.byId));assertTrue(new ProofVerifier().verify(new ObjectMapper().valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", cn.bidcheck.compat.Java8Api.listOf(forged))),c.all).facts().isEmpty());}
 @Test void completeMemberSelectorsPreserveTwoConcreteCompanies(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),agreement(PROJECT));for(String role:cn.bidcheck.compat.Java8Api.listOf("联合体成员", "联合体成员单位", "各成员", "全部成员", "本项目联合体所有成员")){cn.bidcheck.verification.engine.VerificationTypes.Rule r=rule("MATERIAL",role);java.util.List<cn.bidcheck.verification.engine.VerificationTypes.Fact> fs=facts(c,r);assertEquals(cn.bidcheck.compat.Java8Api.setOf(A, B),new HashSet<>(DomainBindings.subjects(role,fs,c)),role);assertFalse(DomainBindings.completeMemberSet(role,DomainBindings.roleLinks(role,fs,c),DomainBindings.subjects(role,fs,c),c).isEmpty(),role);}}
 @Test void completeMemberSelectorsNeverBecomeLeadOnlyForPartialSource(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),"联合体协议书\n共同投标"+PROJECT+"/标段。\n"+A+"为联合体牵头人。\n其余成员另见附件。");for(String role:cn.bidcheck.compat.Java8Api.listOf("全部成员", "各成员"))assertTrue(facts(c,rule("MATERIAL",role)).isEmpty());}
 @Test void publishedNativePartyEdgesReloadWithSourceValidationWithoutBusinessReadCredit(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter(),"营业执照扫描件");cn.bidcheck.verification.engine.VerificationTypes.Rule r=rule("MATERIAL","投标人");java.util.List<cn.bidcheck.verification.engine.VerificationTypes.Fact> fs=facts(c,r);cn.bidcheck.verification.engine.SharedFactReuseTest fixture=new SharedFactReuseTest();cn.bidcheck.verification.engine.SharedFactReuseTest.MemoryLedger ledger=fixture.new MemoryLedger();List<Source> exact=cn.bidcheck.compat.Java8Api.toList(fs.stream().flatMap(f->f.sourceIds().stream()).distinct().map(c.byId::get));new SharedFactReuse(c,ledger.context(),"model","engine").publish(fs,exact,cn.bidcheck.compat.Java8Api.listOf(r),cn.bidcheck.compat.Java8Api.listOf(),false,"NATIVE");assertFalse(ledger.batches.isEmpty());assertTrue(ledger.batches.stream().allMatch(b->RuleEvaluator.maps(b.get("fieldCoverage")).isEmpty()&&!b.containsKey("extractionCoverage")));java.util.List<cn.bidcheck.verification.engine.VerificationTypes.Fact> reloaded=new SharedFactReuse(c,ledger.context(),"model","engine").lookup(cn.bidcheck.compat.Java8Api.listOf(r),c.all,cn.bidcheck.compat.Java8Api.listOf());assertEquals(cn.bidcheck.compat.Java8Api.setOf(A, B),new HashSet<>(DomainBindings.subjects("投标人",reloaded,c)));assertEquals("UNDETERMINED",new RuleEvaluator(reloaded,c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(r).status());}
 @Test void initialComputationAlreadyKnowsCompaniesBeforeAnyBusinessExtraction(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus(cover(),letter());ObjectMapper json=new ObjectMapper();cn.bidcheck.verification.engine.VerificationTypes.Rule r=rule("MATERIAL","投标人");ModelGateway mock=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "enterprise-offline-test";}public com.fasterxml.jackson.databind.JsonNode request(String operation,Map<String,Object> input){return json.valueToTree(operation.equals("COMPILE")?cn.bidcheck.compat.Java8Api.mapOf("logic", "ALL", "rules", cn.bidcheck.compat.Java8Api.listOf(r)):cn.bidcheck.compat.Java8Api.mapOf("facts", cn.bidcheck.compat.Java8Api.listOf()));}};cn.bidcheck.domain.Domain.Checkpoint cp=new cn.bidcheck.domain.Domain.Checkpoint("enterprise","营业执照","资格","HIGH","SEMANTIC_RESPONSE","","",r.sourceQuote(),"",true,true,true,null);Map<String,Object> result=new VerificationEngine(mock,null).evaluate(cp,c.documents,null,cn.bidcheck.compat.Java8Api.mapOf());Map<String,Object> initial=RuleEvaluator.maps(result.get("steps")).stream().filter(s->"RULE_COMPUTATION_INITIAL".equals(s.get("type"))).findFirst().orElseThrow(java.util.NoSuchElementException::new);String output=initial.get("output").toString();assertTrue(output.contains(A)&&output.contains(B),output);assertFalse(output.contains("SUBJECT_RELATION_UNPROVEN"),output);}
}
